module hash_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [24:0] K,\n    input wire [4:0] M,\n    output reg [47:0] result,\n    output reg done\n);\n    \n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] COMPUTE     = 3'd1;\n    localparam [2:0] UPDATE      = 3'd2;\n    localparam [2:0] CHECK_DONE  = 3'd3;\n    localparam [2:0] FINISH      = 3'd4;\n    \n    // Internal signals\n    reg [2:0] state;\n    reg [3:0] len_counter;\n    reg [24:0] state_counter;\n    reg [24:0] MOD;\n    reg [4:0] letter_counter;\n    reg [47:0] dp_current [0:255];\n    reg [47:0] dp_next [0:255];\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            done <= 1'b0;\n            result <= 48'd0;\n            len_counter <= 4'd0;\n            state_counter <= 25'd0;\n            letter_counter <= 5'd0;\n            state <= IDLE;\n            MOD <= 25'd1 << M;\n            \n            // Initialize DP arrays\n            for (i = 0; i < 256; i = i + 1) begin\n                dp_current[i] <= 48'd0;\n                dp_next[i] <= 48'd0;\n            end\n            dp_current[0] <= 48'd1;\n        end else begin\n            MOD <= 25'd1 << M;  // Update MOD if M changes\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 48'd0;\n                    if (start) begin\n                        // Initialize DP_next\n                        for (i = 0; i < 256; i = i + 1) begin\n                            dp_next[i] <= 48'd0;\n                        end\n                        len_counter <= 4'd1;\n                        state_counter <= 25'd0;\n                        letter_counter <= 5'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (letter_counter < 5'd26) begin\n                        // new_state = (state * 33) ^ (letter+1) mod MOD\n                        reg [24:0] new_state;\n                        new_state = ((state_counter * 25'd33) ^ (25'd1 + letter_counter)) % MOD;\n                        dp_next[new_state] <= dp_next[new_state] + dp_current[state_counter];\n                        letter_counter <= letter_counter + 5'd1;\n                    end else begin\n                        state <= UPDATE;\n                        letter_counter <= 5'd0;\n                    end\n                end\n                \n                UPDATE: begin\n                    if (state_counter < (MOD - 25'd1)) begin\n                        state_counter <= state_counter + 25'd1;\n                        state <= COMPUTE;\n                    end else begin\n                        state_counter <= 25'd0;\n                        state <= CHECK_DONE;\n                    end\n                end\n                \n                CHECK_DONE: begin\n                    // Update dp_current\n                    for (i = 0; i < 256; i = i + 1) begin\n                        dp_current[i] <= (i < MOD) ? dp_next[i] : 48'd0;\n                        dp_next[i] <= 48'd0;\n                    end\n                    \n                    if (len_counter >= N) begin\n                        state <= FINISH;\n                    end else begin\n                        len_counter <= len_counter + 4'd1;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                FINISH: begin\n                    result <= (K < MOD) ? dp_current[K] : 48'd0;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule